select 'N53' q, count(*) c, sum(p.id) s from p where exists (select 1 from d where d.k = p.k and d.k = p.j);
select 'N54' q, count(*) c, sum(p.id) s from p where not exists (select 1 from u where u.id = p.k);
select 'N55' q, count(*) c, sum(p.id) s from p where not exists (select 1 from u where u.id = p.k and u.j = p.j);
select 'N56' q, count(*) c, sum(p1.id) s from p p1 where not exists (select 1 from p p2 where p2.k = p1.id);
select 'N57' q, count(*) c, sum(d.id) s from d where d.x = 1 and not exists (select 1 from p where p.k = d.k and p.j = d.j);
update p set x = x + 100 where not exists (select 1 from d where d.k = p.k);
select 'N58' q, count(*) c, sum(p.id) s from p where x >= 100;
rollback;
delete from p where not exists (select 1 from d where d.k = p.k and p.x = 3);
select 'N59' q, count(*) c, sum(p.id) s from p;
rollback;
delete from p where not exists (select 1 from p p2 where p2.k = p.id);
select 'N60' q, count(*) c, sum(p.id) s from p;
rollback;
